3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"net/http"
10		"net/url"
11		"strconv"
12		"strings"
13		"unicode"
14	)
15	
16	// maxCatalogPage bounds one _catalog page: 1000 names of at most 255 bytes fit
17	// well under it.
18	const maxCatalogPage = 1 << 20
19	
20	// Bounds on a catalog prefix: a repository path segment holds at most 255
21	// bytes and a whole name at most 1024 here, so a longer prefix names nothing
22	// and is refused before any request.
23	const (
24		maxCatalogPrefixSegment = 255
25		maxCatalogPrefix        = 1024
26	)
27	
28	// ListCatalogContext walks the registry's /v2/_catalog from apiURL; it is
29	// ListCatalogUnderContext with an empty prefix.
30	func ListCatalogContext(ctx context.Context, apiURL, username, password string, maxPages, pageSize int) (names []string, truncated bool, err error) {
31		return ListCatalogUnderContext(ctx, apiURL, "", username, password, maxPages, pageSize)
32	}
33	
34	// ListCatalogUnderContext walks the catalog of the repository at prefix,
35	// /v2/<prefix>/_catalog (a Nexus group member, DEVDESK-579), or the registry's
36	// /v2/_catalog when prefix is empty. Names come back as the server sent them,
37	// without the prefix: rebuilding "<prefix>/<name>" is the caller's job.
38	// It asks pageSize names per page and follows Link rel="next" for at most
39	// maxPages pages. truncated is true when the walk stopped with names left: page
40	// cap reached with a next link, more than maxPages*pageSize names, or a next
41	// link to another origin (never followed: the Basic credentials and the token
42	// are not sent to it). HTTP 3xx redirects follow registryHTTPClient, which
43	// refuses off-origin ones (RefuseOffOriginRedirect, DEVDESK-410).
44	// Authentication is the tag flow's (Basic, then Bearer on a challenge, token
45	// kept across pages); a non-200 answer is a *StatusError. A prefix that
46	// checkCatalogPrefix refuses is an error before any request.
47	// With a non-empty prefix a next link is also followed only when its escaped
48	// path is exactly the member's catalog path: a link to /v2/_catalog or to
49	// another repository would attach names of another catalog to the prefix, so
50	// it ends the walk as truncated, unfollowed. With an empty prefix any
51	// same-origin path is followed, as ListCatalogContext always did.
52	func ListCatalogUnderContext(ctx context.Context, apiURL, prefix, username, password string, maxPages, pageSize int) (names []string, truncated bool, err error) {
53		if maxPages <= 0 || pageSize <= 0 {
54			return nil, false, fmt.Errorf("catalog walk needs positive limits, got %d pages of %d", maxPages, pageSize)
55		}
56		path, err := catalogPath(prefix)
57		if err != nil {
58			return nil, false, err
59		}
60		next := strings.TrimSuffix(apiURL, "/") + path + "?n=" + strconv.Itoa(pageSize)
61		// memberPath is the only path a next link may take; "" means no constraint.
62		memberPath := ""
63		if prefix != "" {
64			memberPath = path
65		}
66		token := ""
67		for page := 0; next != ""; page++ {
68			if page == maxPages {
69				return names, true, nil
70			}
71			body, link, usedToken, err := registryGETBoundedContext(ctx, next, username, password, token, maxCatalogPage)
72			if err != nil {
73				return nil, false, err
74			}
75			token = usedToken
76			var result struct {
77				Repositories []string `json:"repositories"`
78			}
79			if err := json.Unmarshal(body, &result); err != nil {
80				return nil, false, fmt.Errorf("decode catalog response: %w", err)
81			}
82			names = append(names, result.Repositories...)
83			if len(names) > maxPages*pageSize {
84				return names[:maxPages*pageSize], true, nil
85			}
86			current := next
87			if next = resolveNext(current, link); next != "" && (!sameOrigin(current, next) || !onCatalogPath(next, memberPath)) {
88				return names, true, nil
89			}
90		}
91		return names, false, nil
92	}
93	
94	// catalogPath is the escaped catalog path for prefix: "/v2/_catalog" for an
95	// empty prefix, "/v2/<seg>/<seg>/_catalog" otherwise, each segment escaped
96	// with url.PathEscape so it stays one path segment on the wire.
97	func catalogPath(prefix string) (string, error) {
98		if prefix == "" {
99			return "/v2/_catalog", nil
100		}
101		if err := checkCatalogPrefix(prefix); err != nil {
102			return "", err
103		}
104		segments := strings.Split(prefix, "/")
105		for i, seg := range segments {
106			segments[i] = url.PathEscape(seg)
107		}
108		return "/v2/" + strings.Join(segments, "/") + "/_catalog", nil
109	}
110	
111	// onCatalogPath reports whether rawURL's escaped path is exactly want; an empty
112	// want accepts any path. An unparsable URL is refused.
113	func onCatalogPath(rawURL, want string) bool {
114		if want == "" {
115			return true
116		}
117		u, err := url.Parse(rawURL)
118		return err == nil && u.EscapedPath() == want
119	}
120	
121	// checkCatalogPrefix refuses, before any request, a prefix that could leave
122	// the member's catalog path or that no repository name holds: an empty segment
123	// (so a leading, trailing or doubled slash), "." or "..", any ".." (read
124	// literally, so "a..b" too), a backslash, a segment of spaces only, and any
125	// control character (NUL included), a segment over 255 bytes and a prefix over
126	// 1024 bytes. The error names the rule, never the prefix or any credential.
127	func checkCatalogPrefix(prefix string) error {
128		if len(prefix) > maxCatalogPrefix {
129			return fmt.Errorf("catalog prefix refused: longer than %d bytes", maxCatalogPrefix)
130		}
131		if strings.Contains(prefix, "..") {
132			return errors.New("catalog prefix refused: contains \"..\"")
133		}
134		if strings.ContainsRune(prefix, '\\') {
135			return errors.New("catalog prefix refused: contains a backslash")
136		}
137		if strings.IndexFunc(prefix, unicode.IsControl) >= 0 {
138			return errors.New("catalog prefix refused: contains a control character")
139		}
140		for _, seg := range strings.Split(prefix, "/") {
141			switch {
142			case seg == "":
143				return errors.New("catalog prefix refused: empty path segment")
144			case seg == ".":
145				return errors.New("catalog prefix refused: \".\" path segment")
146			case strings.TrimSpace(seg) == "":
147				return errors.New("catalog prefix refused: blank path segment")
148			case len(seg) > maxCatalogPrefixSegment:
149				return fmt.Errorf("catalog prefix refused: path segment longer than %d bytes", maxCatalogPrefixSegment)
150			}
151		}
152		return nil
153	}
154	
155	// registryGETBoundedContext is registryGETContext with an explicit body cap:
156	// a body over limit is an error, not a silent cut.
157	func registryGETBoundedContext(ctx context.Context, rawURL, username, password, token string, limit int64) (body []byte, link, usedToken string, err error) {
158		resp, token, err := registryDoContext(ctx, http.MethodGet, rawURL, "", username, password, token)
159		if err != nil {
160			return nil, "", token, err
161		}
162		defer func() { _ = resp.Body.Close() }()
163		if resp.StatusCode != http.StatusOK {
164			return nil, "", token, &StatusError{Code: resp.StatusCode, Source: SourceRegistry}
165		}
166		body, err = io.ReadAll(io.LimitReader(resp.Body, limit+1))
167		if err == nil && int64(len(body)) > limit {
168			err = errors.New("catalog page over " + strconv.FormatInt(limit, 10) + " bytes")
169		}
170		if err != nil {
171			return nil, "", token, err
172		}
173		return body, resp.Header.Get("Link"), token, nil
174	}
175	
176	// sameOrigin reports whether two absolute URLs share scheme, host and port.
177	func sameOrigin(a, b string) bool {
178		ua, errA := url.Parse(a)
179		ub, errB := url.Parse(b)
180		return errA == nil && errB == nil && ua.Scheme == ub.Scheme && ua.Host == ub.Host
181	}
