66		token := ""
67		for page := 0; next != ""; page++ {
68			if page == maxPages {
69				return names, true, nil
70			}
71			body, link, usedToken, err := registryGETBoundedContext(ctx, next, username, password, token, maxCatalogPage)
72			if err != nil {
73				return nil, false, err
74			}
75			token = usedToken
76			var result struct {
77				Repositories []string `json:"repositories"`
78			}
79			if err := json.Unmarshal(body, &result); err != nil {
80				return nil, false, fmt.Errorf("decode catalog response: %w", err)
81			}
82			names = append(names, result.Repositories...)
83			if len(names) > maxPages*pageSize {
84				return names[:maxPages*pageSize], true, nil
85			}
86			current := next
87			if next = resolveNext(current, link); next != "" && (!sameOrigin(current, next) || !onCatalogPath(next, memberPath)) {
