94	// catalogPath is the escaped catalog path for prefix: "/v2/_catalog" for an
95	// empty prefix, "/v2/<seg>/<seg>/_catalog" otherwise, each segment escaped
96	// with url.PathEscape so it stays one path segment on the wire.
97	func catalogPath(prefix string) (string, error) {
98		if prefix == "" {
99			return "/v2/_catalog", nil
100		}
101		if err := checkCatalogPrefix(prefix); err != nil {
102			return "", err
103		}
104		segments := strings.Split(prefix, "/")
105		for i, seg := range segments {
106			segments[i] = url.PathEscape(seg)
107		}
108		return "/v2/" + strings.Join(segments, "/") + "/_catalog", nil
109	}
110	
111	// onCatalogPath reports whether rawURL's escaped path is exactly want; an empty
112	// want accepts any path. An unparsable URL is refused.
113	func onCatalogPath(rawURL, want string) bool {
114		if want == "" {
115			return true
116		}
117		u, err := url.Parse(rawURL)
118		return err == nil && u.EscapedPath() == want
119	}
120	
121	// checkCatalogPrefix refuses, before any request, a prefix that could leave
122	// the member's catalog path or that no repository name holds: an empty segment
123	// (so a leading, trailing or doubled slash), "." or "..", any ".." (read
124	// literally, so "a..b" too), a backslash, a segment of spaces only, and any
125	// control character (NUL included), a segment over 255 bytes and a prefix over
126	// 1024 bytes. The error names the rule, never the prefix or any credential.
127	func checkCatalogPrefix(prefix string) error {
128		if len(prefix) > maxCatalogPrefix {
129			return fmt.Errorf("catalog prefix refused: longer than %d bytes", maxCatalogPrefix)
130		}
131		if strings.Contains(prefix, "..") {
132			return errors.New("catalog prefix refused: contains \"..\"")
133		}
134		if strings.ContainsRune(prefix, '\\') {
135			return errors.New("catalog prefix refused: contains a backslash")
136		}
137		if strings.IndexFunc(prefix, unicode.IsControl) >= 0 {
138			return errors.New("catalog prefix refused: contains a control character")
139		}
140		for _, seg := range strings.Split(prefix, "/") {
141			switch {
142			case seg == "":
143				return errors.New("catalog prefix refused: empty path segment")
144			case seg == ".":
145				return errors.New("catalog prefix refused: \".\" path segment")
146			case strings.TrimSpace(seg) == "":
147				return errors.New("catalog prefix refused: blank path segment")
148			case len(seg) > maxCatalogPrefixSegment:
149				return fmt.Errorf("catalog prefix refused: path segment longer than %d bytes", maxCatalogPrefixSegment)
150			}
151		}
152		return nil
153	}
