64	// AuthFilePath is the credential file the engine reads and writes, or "" when
65	// it cannot be located. Named in the UI when a secret sits in it (§3.68).
66	func AuthFilePath() string {
67		path, err := authPath()
68		if err != nil {
69			return ""
70		}
