92	// rootRows filters a root catalog: names must carry the entry's prefix (R1),
93	// which is stripped from Name. sawPrefix tells whether any name carried it.
94	func rootRows(t Target, names []string, text string) (rows []Image, sawPrefix bool) {
95		prefix := strings.Trim(t.RepoPrefix, "/")
96		needle := strings.ToLower(text)
97		for _, name := range names {
98			rest := name
99			if prefix != "" {
100				var ok bool
101				if rest, ok = strings.CutPrefix(name, prefix+"/"); !ok {
102					continue
103				}
104				sawPrefix = true
105			}
106			if !validRepoPath(name) {
107				continue
108			}
109			if strings.Contains(strings.ToLower(rest), needle) {
110				rows = append(rows, Image{EntryKey: t.EntryKey, Name: rest, Repo: name})
111			}
112		}
113		return rows, sawPrefix
114	}
