116	// underPrefixRows filters the catalog of a member read under its own path: the
117	// names are relative to RepoPrefix, so none is expected to carry it (no R1) and
118	// Repo is rebuilt as "<prefix>/<name>".
119	func underPrefixRows(t Target, names []string, text string) []Image {
120		needle := strings.ToLower(text)
121		var rows []Image
122		for _, name := range names {
123			if !validRepoPath(name) {
124				continue
125			}
126			if strings.Contains(strings.ToLower(name), needle) {
127				rows = append(rows, Image{EntryKey: t.EntryKey, Name: name, Repo: t.RepoPrefix + "/" + name})
128			}
129		}
130		return rows
131	}
